//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDSTF10950.xml';
scwin.gLdMktTp = js_market;
scwin.arrMKT = [9, 1, 2, 6];
scwin.arrFORM = [1, 2, 3, 4];
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    // 현재날짜 셋팅	
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));
};
scwin.fn_Init = function() {
    checkbox_MKT0.setValue(1);
    chb_MKT0.setValue(1);
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
        eval("chb_MKT" + scwin.arrMKT[i]).setValue(1);
    }
    panel_MKT1.style.visibility = "";
    panel_MKT2.style.visibility = "";
    panel_MKT6.style.visibility = "";
};
scwin.fn_getCheckedMKT = function() {
    var text = "";
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            text.setValue(text.getValue() + scwin.arrMKT[i] + ",");
        }
    }
    return text;
};
scwin.fn_getCheckedFORM = function() {
    var text = "";
    for (var i = 0, j = 0; i < scwin.arrFORM.length; i++) {
        if (eval("checkbox_FORM" + scwin.arrFORM[i]).checked) {
            text.setValue(text.getValue() + scwin.arrFORM[i] + ",");
            j++;
        }
    }
    /*
    if(j == arrFORM.length) {	//전체 체크되면 빈값을 보냄
    	text = "";
    }
    */
    return text;
};
scwin.fn_getCheckedMKT2 = function() {
    var text = "";
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("chb_MKT" + scwin.arrMKT[i]).checked) {
            text.setValue(text.getValue() + scwin.arrMKT[i] + ",");
        }
    }
    return text;
};
scwin.fn_validCheck = function() {
    var a = 0,
        b = 0;
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
            a++;
        }
    }
    if (a == 0) {
        $c.win.alert("시장구분을 선택해 주세요.");
        checkbox_MKT0.focus();
        return false;
    }
    /*
    for(var i=0; i<arrFORM.length; i++) {
    	if(eval("checkbox_FORM" + arrFORM[i]).checked) {
    		b++;
    	}
    }
    if(b == 0) {
    	alert("서식구분을 선택해 주세요.");
    	checkbox_FORM0.focus();
    	return false;
    }
    */
    return true;
};
scwin.fn_validCheck2 = function() {
    var a = 0;
    for (var i = 0; i < scwin.arrMKT.length; i++) {
        if (eval("chb_MKT" + scwin.arrMKT[i]).checked) {
            a++;
        }
    }
    if (a == 0) {
        $c.win.alert("시장구분을 선택해 주세요.");
        chb_MKT0.focus();
        return false;
    }
    return true;
};
scwin.fn_Search = function() {
    if (!scwin.fn_validCheck()) return;
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    var url = "/MktActNotice.do?method=listJntDisclsMng" + "&ACPT_DATE=" + "&LD_MKT_TP=" + scwin.fn_getCheckedMKT() + "&FORM_PROCS_CD=" + scwin.fn_getCheckedFORM() + "&FORM_KOR_NM=" + $c.stf.getObjectValue(txb_FORM_NM) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DisclsForm.DataID = encodeURI(url);
    dts_DisclsForm.reset();
    $c.cm.ShowWin(grd_DisclsForm);
};
scwin.fn_SearchTap2 = function() {
    if (!scwin.fn_validCheck2()) return;
    btn_Search2.setDisabled(true);
    btn_Search2.src = "../img/btn_select_d.gif";
    var url = "/MktActNotice.do?method=listJntDisclsMng" + "&ACPT_DATE=" + $c.stf.getObjectValue(edt_SrchDay) + "&LD_MKT_TP=" + scwin.fn_getCheckedMKT2() + "&FORM_PROCS_CD=1" + "&FORM_KOR_NM=" + $c.stf.getObjectValue(txb_FORM_NM2) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_JntForm.DataID = encodeURI(url);
    dts_JntForm.reset();
    $c.cm.ShowWin(grd_JntForm);
};
scwin.fn_SearchRegHist = function(sFORM_CD, sFORM_NM) {
    label_FORM_CD.childNodes[0].innerText = "(" + sFORM_CD + ") " + sFORM_NM;
    var url = "/MktActNotice.do?method=listJntDisclsRegHist" + "&FORM_CD=" + sFORM_CD + "&FORM_PROCS_CD=1" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_JntHist.DataID = encodeURI(url);
    dts_JntHist.reset();
    $c.cm.ShowWin(grd_JntHist);
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인해 주세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인해 주세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength3 = function(text, size, lbl) {
    var overLen = eval($c.stf.getStringSize(text) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인해 주세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return false;
    }
    return true;
};
scwin.fn_CheckBndCls = function() {
    //채권 마감여부 조회
    var url = "/MktActNotice.do?method=getBndCloseYn" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_CloseYn.DataID = encodeURI(url);
    dts_CloseYn.reset();
};
scwin.fn_Save = function(sCLOSE_YN) {
    if (sCLOSE_YN == 'Y') {
        $c.win.alert("채권상장마감(BNS30300) 이후로는 등록ㆍ해제 변경 불가합니다.");
        return;
    }
    if (!scwin.fn_validSaveParamCheck(dts_DisclsForm)) {
        return;
    }
    scwin.fn_SetHeader();
    var gCnt = 1;
    for (var i = 1; i <= dts_DisclsForm.getTotalRow(); i++) {
        if (dts_DisclsForm.getCellData(i, "CHK_FLAG") == 1 || dts_DisclsForm.getCellData(i, "CHK_FLAG") == "T") {
            dts_Save.insertRow();
            dts_Save.setCellData(gCnt, "FORM_CD", dts_DisclsForm.getCellData(i, "FORM_CD"));
            dts_Save.setCellData(gCnt, "SEQ", dts_DisclsForm.getCellData(i, "SEQ"));
            dts_Save.setCellData(gCnt, "FORM_PROCS_CD", dts_DisclsForm.getCellData(i, "FORM_PROCS_CD"));
            dts_Save.setCellData(gCnt, "TOBE_FORM_PROCS_CD", dts_DisclsForm.getCellData(i, "TOBE_FORM_PROCS_CD"));
            dts_Save.setCellData(gCnt, "TOBE_FORM_WARN_CONTN", dts_DisclsForm.getCellData(i, "TOBE_FORM_WARN_CONTN"));
            dts_Save.setCellData(gCnt, "TOBE_SEQ", dts_DisclsForm.getCellData(i, "TOBE_SEQ"));
            dts_Save.setCellData(gCnt, "JNT_DISCLS_TP_CD", dts_DisclsForm.getCellData(i, "JNT_DISCLS_TP_CD"));
            dts_Save.setCellData(gCnt, "TRANSTR_EMP_NO", js_emp_no);
            gCnt++;

            //alert(dts_Save.NameValue(1, "TOBE_FORM_WARN_CONTN") + "_" + dts_Save.CountRow);
            /*
            alert(
            	dts_Save.NameValue(1, "FORM_CD") + "\n" + 
            	dts_Save.NameValue(1, "SEQ") + "\n" + 
            	dts_Save.NameValue(1, "TOBE_FORM_PROCS_CD") + "\n" + 
            	dts_Save.NameValue(1, "TOBE_FORM_WARN_CONTN") + "\n" + 
            	dts_Save.NameValue(1, "TOBE_SEQ") + "\n" + 
            	dts_Save.NameValue(1, "TRANSTR_EMP_NO") + "\n"
            );
            */

        }
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + (gCnt - 1) + '건을 저장'))) return;
    trs_Save.Action = "/MktActNotice.do?method=saveJntDisclsMng&EMP_NO=" + js_emp_no + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput1=dts_Save)";
    trs_Save.Post();
};
scwin.fn_validSaveParamCheck = function() {
    //alert(dts_DisclsForm.NameValue(2, "TOBE_FORM_PROCS_CD") + "_" + dts_DisclsForm.NameString(2, "TOBE_FORM_PROCS_CD"));
    var cCnt = 0;
    for (i = 1; i <= dts_DisclsForm.getTotalRow(); i++) {
        if (dts_DisclsForm.getCellData(i, "CHK_FLAG") == 1 || dts_DisclsForm.getCellData(i, "CHK_FLAG") == "T") {
            cCnt++;
            if (dts_DisclsForm.getCellData(i, "TOBE_FORM_PROCS_CD") == "") {
                dts_DisclsForm.setRowPosition(i, 0);
                $c.win.alert("서식구분을 선택해 주세요.");
                grd_DisclsForm.SetColumn("TOBE_FORM_PROCS_CD");
                grd_DisclsForm.focus();
                return false;
            } else if (dts_DisclsForm.getCellData(i, "TOBE_FORM_PROCS_CD") == "132") {
                /*
                if(dts_DisclsForm.NameString(i, "TOBE_FORM_WARN_CONTN") == "") {
                	dts_DisclsForm.Rowposition = i;
                	alert("유의사항을 입력해 주세요.");
                	grd_DisclsForm.SetColumn("TOBE_FORM_WARN_CONTN");
                	grd_DisclsForm.Focus();
                	return false;
                }
                */
                if (!scwin.checkMaxLength3(dts_DisclsForm.getCellData(i, "TOBE_FORM_WARN_CONTN"), 40, "유의사항")) {
                    dts_DisclsForm.setRowPosition(i, 0);
                    grd_DisclsForm.SetColumn("TOBE_FORM_WARN_CONTN");
                    grd_DisclsForm.focus();
                    return false;
                }
            }
        }
    }
    if (cCnt == 0) {
        $c.win.alert("선택한 항목이 없습니다.");
        return false;
    }
    return true;
};
scwin.fn_SetHeader = function() {
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LIST_JNT_DISCLS_MNG_INOUT";
    dts_Save.reset();
};
scwin.fn_checkbox_FORM = function(flag) {
    if (flag == "0") {
        //전체
        if (checkbox_FORM0.checked) {
            for (var i = 0; i < scwin.arrFORM.length; i++) {
                eval("checkbox_FORM" + scwin.arrFORM[i]).setValue(1);
            }
        } else {
            for (var i = 0; i < scwin.arrFORM.length; i++) {
                eval("checkbox_FORM" + scwin.arrFORM[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 0; i < scwin.arrFORM.length; i++) {
            if (!eval("checkbox_FORM" + scwin.arrFORM[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            checkbox_FORM0.setValue(1);
        } else {
            checkbox_FORM0.setValue(0);
        }
    }
};
scwin.fn_checkbox_MKT = function(flag) {
    if (flag == "0") {
        //전체
        if (checkbox_MKT0.checked) {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(1);
            }
        } else {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("checkbox_MKT" + scwin.arrMKT[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 0; i < scwin.arrMKT.length; i++) {
            if (!eval("checkbox_MKT" + scwin.arrMKT[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            checkbox_MKT0.setValue(1);
        } else {
            checkbox_MKT0.setValue(0);
        }
    }
};
scwin.fn_chb_MKT = function(flag) {
    if (flag == "0") {
        //전체
        if (chb_MKT0.checked) {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("chb_MKT" + scwin.arrMKT[i]).setValue(1);
            }
        } else {
            for (var i = 0; i < scwin.arrMKT.length; i++) {
                eval("chb_MKT" + scwin.arrMKT[i]).setValue(0);
            }
        }
    } else {
        var a = 0;
        for (var i = 0; i < scwin.arrMKT.length; i++) {
            if (!eval("chb_MKT" + scwin.arrMKT[i]).checked) {
                a++;
            }
        }
        if (a == 0) {
            chb_MKT0.setValue(1);
        } else {
            chb_MKT0.setValue(0);
        }
    }
};
scwin.fn_onColumnChanged = function(row, colid) {
    if (colid == "TOBE_FORM_PROCS_CD" || colid == "TOBE_FORM_WARN_CONTN") {
        if (dts_DisclsForm.getCellData(row, "TOBE_FORM_PROCS_CD") != "132") {
            //공동공시 아닌것은 유의사항 삭제
            dts_DisclsForm.setCellData(row, "TOBE_FORM_WARN_CONTN", "");
        } else {
            //공동공시인 경우 유의사항 40BYTE 확인
            if (!scwin.checkMaxLength3(dts_DisclsForm.getCellData(row, "TOBE_FORM_WARN_CONTN"), 40, "유의사항")) return;
        }
    }
};
scwin.fn_chk_cancle = function(sval) {
    //데이터셋 체크박스 초기화
    for (var i = 1; i <= sval.getTotalRow(); i++) {
        sval.setCellData(i, "CHK_FLAG", 0);
    }
};
scwin.fn_undo = function(sval) {
    sval.undoall();
};
scwin.dts_JntHist_OnLoadCompleted = function(rowcount) {

};
scwin.dts_JntHist_OnLoadError = function() {
    $c.stf.alert_error(dts_JntHist);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    scwin.fn_Search();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    //alert('MxTab_1.OnSelChanged('+nIndex+')');
    //if (nIndex == 2) {PanelToGroupBox_01(panel_3);}
    if (nIndex == 1) {
        // 탭인덱스 1
        scwin.fn_Search();
    } else if (nIndex == 2) {
        //탭인덱스 2
        scwin.fn_SearchTap2();
    } else {

    }
};
scwin.dts_DisclsForm_OnLoadError = function() {
    $c.stf.alert_error(dts_DisclsForm);
    $c.cm.CloseWin('', grd_DisclsForm);
};
scwin.dts_DisclsForm_OnLoadCompleted = function(rowcount) {
    if (dts_DisclsForm.errorMsg) {
        $c.win.alert(dts_DisclsForm.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
    $c.cm.CloseWin(rowcount, grd_DisclsForm);
};
scwin.dts_CloseYn_OnLoadError = function() {
    $c.stf.alert_error(dts_CloseYn);
};
scwin.dts_CloseYn_OnLoadCompleted = function(rowcount) {
    if (dts_CloseYn.errorMsg) {
        $c.win.alert(dts_CloseYn.errorMsg);
    } else {
        scwin.fn_Save(dts_CloseYn.getCellData(1, "CLOSE_YN"));
    }
};
scwin.dts_JntForm_OnLoadError = function() {
    $c.stf.alert_error(dts_JntForm);
    $c.cm.CloseWin('', grd_JntForm);
};
scwin.dts_JntForm_OnLoadCompleted = function(rowcount) {
    if (dts_JntForm.errorMsg) {
        $c.win.alert(dts_JntForm.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_left);
    }
    dts_JntHist.removeAll();
    label_FORM_CD.childNodes[0].innerText = "";
    if (rowcount > 0) {
        scwin.fn_SearchRegHist(dts_JntForm.getCellData(1, "FORM_CD"), dts_JntForm.getCellData(1, "FORM_KOR_NM"));
    }
    btn_Search2.setDisabled(false);
    btn_Search2.src = "../img/btn_select.gif";
    $c.cm.CloseWin(rowcount, grd_JntForm);
};
scwin.grd_JntForm_OnClick = function(row, colid) {
    scwin.fn_SearchRegHist(dts_JntForm.getCellData(row, "FORM_CD"), dts_JntForm.getCellData(row, "FORM_KOR_NM"));
};
scwin.dts_JntHist_OnLoadError = function() {
    $c.stf.alert_error(dts_JntHist);
    $c.cm.CloseWin('', grd_JntHist);
};
scwin.dts_JntHist_OnLoadCompleted = function(rowcount) {
    if (dts_JntHist.errorMsg) {
        $c.win.alert(dts_JntHist.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_right);
    }
    $c.cm.CloseWin(rowcount, grd_JntHist);
};
scwin.img_Cal_onclick = function() {
    popUpCalendar2(edt_SrchDay);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox_01(panel_2);
    $c.cm.PanelToGroupBox_01(panel_3);
    scwin.fn_Init();
    scwin.fn_SetCode();
    scwin.fn_Search();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Search2_onclick = function() {
    scwin.fn_SearchTap2();
};
scwin.grd_DisclsForm_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.grd_DisclsForm_OnHeadCheckClick = function(col, colid, bCheck) {
    var gcnt = dts_DisclsForm.getTotalRow();
    var chk = "F";
    if (gcnt > 0) {
        grd_DisclsForm.Redraw = false;
        if (bCheck == 1) chk = "T";
        for (var i = 1; i <= gcnt; i++) {
            dts_DisclsForm.setCellData(i, "CHK_FLAG", chk);
        }
        grd_DisclsForm.Redraw = true;
    }
};
scwin.btn_Save_onclick = function() {
    //채권마감여부 확인
    scwin.fn_CheckBndCls();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var file_name = "공동공시관리";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_DisclsForm, file_name, xls_path, "8", 0);
    //grd_DisclsForm.GridToExcel("공동공시관리", "", "8");

};
scwin.checkbox_FORM0_onclick = function() {
    scwin.fn_checkbox_FORM(0);
};
scwin.checkbox_FORM1_onclick = function() {
    scwin.fn_checkbox_FORM(1);
};
